 'use strict';
navOwner.splice(navOwner.findIndex(n=>n[0]==='join')+1,0,['branches','building','الفروع']);
let branchFilter='all',operationCard='all',operationKind='all',operationEmployee='all',operationSearch='';
const businessBranches=()=>shop()?.branches||[];
const branchLabel=id=>businessBranches().find(b=>b.id===id)?.name||'بدون فرع';
function branchOptions(selected='',all=false){return `${all?`<option value="all" ${selected==='all'?'selected':''}>جميع الفروع</option>`:''}<option value="" ${selected===''?'selected':''}>بدون فرع</option>`+businessBranches().map(b=>`<option value="${esc(b.id)}" ${b.id===selected?'selected':''}>${esc(b.name)}${b.status==='paused'?' · متوقف':''}</option>`).join('');}
function branchChoices(card=draft){return `<div class="card-option-panel branch-card-options"><h3>فروع البطاقة · اختياري</h3><p class="sub">اترك الخيارات فارغة لتعمل البطاقة في جميع الفروع. عند تحديد فروع، يستطيع موظفوها فقط إدارة هذه البطاقة.</p>${businessBranches().map(b=>`<label class="terms"><input type="checkbox" data-card-branch="${esc(b.id)}" ${(card.branchIds||[]).includes(b.id)?'checked':''}>${esc(b.name)}${b.status==='paused'?' · متوقف':''}</label>`).join('')||'<p class="sub">أضف فرعًا من قائمة الفروع عند الحاجة.</p>'}<button class="btn secondary small" type="button" data-action="nav" data-view="branches">إدارة الفروع</button></div>`;}
function branchSummary(logs){const r=analyticsRange(),rows=[...businessBranches(),{id:'',name:'بدون فرع',status:'active'}];return `<section class="panel mt"><div class="panel-head"><div><h2>أداء الفروع</h2><p>${esc(r.label)} · المبالغ المدخلة من الموظف فقط، والعمليات المتراجع عنها مستبعدة.</p></div></div><div class="table-scroll"><table><thead><tr><th>الفرع</th><th>زيارات</th><th>نقاط مضافة</th><th>مكافآت مصروفة</th><th>عمليات بمبلغ</th><th>مبيعات مسجلة · ريال</th></tr></thead><tbody>${rows.filter(b=>branchFilter==='all'||b.id===branchFilter).map(b=>{const entries=logs.filter(l=>!l.undone&&(l.branchId||'')===b.id&&l.time>=r.start&&l.time<=r.end),stamps=entries.filter(l=>l.type==='stamp'),priced=stamps.filter(l=>Number.isFinite(l.saleAmount));return `<tr><td>${esc(b.name)}${b.status==='paused'?' · متوقف':''}</td><td>${fmt(stamps.length)}</td><td>${fmt(stamps.reduce((n,l)=>n+(l.pointsAdded||0),0))}</td><td>${fmt(entries.filter(l=>l.type==='redeem').length)}</td><td>${fmt(priced.length)}</td><td>${priced.length?priced.reduce((n,l)=>n+l.saleAmount,0).toLocaleString('ar-SA',{minimumFractionDigits:2,maximumFractionDigits:2}):'لم تُسجل مبالغ'}</td></tr>`;}).join('')}</tbody></table></div></section>`;}
const branchAnalytics=loyaltyAnalytics;
loyaltyAnalytics=function(shops,...args){if(branchFilter!=='all')shops=shops.map(s=>({...s,logs:s.logs.filter(l=>(l.branchId||'')===branchFilter),members:s.members}));return branchAnalytics(shops,...args);};
const branchOwner=ownerHTML;
ownerHTML=function(){
 const cards=db.shops.filter(s=>!s.archivedAt);
 const proBranches=true,branchLimit=RijaaPlans.forAccount(shopAccount()).locations;
 if(view==='branches')return head('توزيع نشاطك','الفروع','اختياري: أضف فروعك، ثم اربط البطاقات والموظفين بها.'+(proBranches?` · ${fmt(businessBranches().length)} من ${fmt(branchLimit)} فرعًا`:''),`<button class="btn primary" data-action="branch-create" ${proBranches&&businessBranches().length>=branchLimit?'disabled':''}>${icon('plus')} إضافة فرع</button>`)+`<div class="branch-grid">${businessBranches().map(b=>`<article class="panel"><span class="pill">${b.status==='active'?'نشط':'متوقف'}</span><h2>${esc(b.name)}</h2><p class="sub">${esc(b.address||'لم يضف عنوان')}</p><div class="branch-counts"><span>${fmt(cards.filter(s=>!s.card.branchIds?.length||s.card.branchIds.includes(b.id)).length)} بطاقة</span><span>${fmt(shop().employees.filter(e=>e.branchId===b.id).length)} موظف</span></div><div class="actions"><button class="btn secondary small" data-action="branch-edit" data-id="${esc(b.id)}">تعديل الفرع</button><button class="btn quiet small" data-action="branch-toggle" data-id="${esc(b.id)}">${b.status==='active'?'إيقاف الفرع':'تفعيل الفرع'}</button></div></article>`).join('')||'<section class="panel"><h2>نشاطك يعمل دون فروع</h2><p>يمكنك إضافة الفروع لاحقًا. تبقى بطاقاتك وعملاؤك وأرصدة الولاء كما هي.</p></section>'}</div>`;
 if(view==='mycards')return head('برامج نشاطك','بطاقاتي','المقاس والتصميم مطابقان لبطاقة الجوال داخل الموقع. مرّر الماوس أو اضغط لإظهار الباركود.',`<button class="btn primary" data-action="new-program" ${cards.length>=RijaaPlans.forAccount(shopAccount()).cards?'disabled':''}>${icon('plus')} بطاقة جديدة</button>`)+`<div class="mobile-card-grid">${cards.map(s=>`<article class="mobile-card-item"><header><h2>${esc(s.card.title||s.name||'بطاقة الولاء')}</h2><p>${s.card.branchIds?.length?s.card.branchIds.map(branchLabel).map(esc).join('، '):'جميع الفروع · أو بدون فروع'}</p></header><div class="mobile-card-peek" role="button" tabindex="0" aria-label="عرض باركود ${esc(s.card.title||s.name)}" aria-expanded="false" data-action="card-peek">${cardHTML(s.card,null,true)}</div><p class="mobile-card-meta">${fmt(s.members.length)} عميل · ${esc(programSummary(s.card))}</p><div class="actions"><button class="btn primary small" data-action="edit-program" data-id="${esc(s.id)}">تعديل البطاقة</button><button class="btn secondary small" data-action="program-customers" data-id="${esc(s.id)}">العملاء (${fmt(s.members.length)})</button><button class="btn quiet small" data-action="delete-program" data-id="${esc(s.id)}">حذف</button></div></article>`).join('')}</div>`+(db.shops.some(s=>s.archivedAt)?`<details class="panel mt"><summary>البطاقات المحذوفة</summary>${db.shops.filter(s=>s.archivedAt).map(s=>`<div class="actions mt"><strong>${esc(s.card.title||s.name)}</strong><button class="btn secondary small" data-action="restore-program" data-id="${esc(s.id)}">استعادة البطاقة</button></div>`).join('')}</details>`:'');
 if(view==='join')return head('انضمام العملاء','روابط تسجيل البطاقات','لكل بطاقة رابط ورمز تسجيل مستقلان. استخدم الرابط الخاص بالبطاقة المطلوبة.')+`<div class="registration-grid">${cards.map(s=>{const url=location.origin+'/?join='+encodeURIComponent(s.id);return `<article class="panel"><h2>${esc(s.card.title||s.name)}</h2><p class="sub">${s.card.branchIds?.length?s.card.branchIds.map(branchLabel).map(esc).join('، '):'متاحة لجميع الفروع'}</p><div class="registration-code">${qr(url)}</div><input class="input" dir="ltr" readonly aria-label="رابط ${esc(s.card.title||s.name)}" value="${esc(url)}"><div class="actions mt"><button class="btn primary small" data-action="branch-copy-link" data-id="${esc(s.id)}">نسخ الرابط</button><button class="btn secondary small" data-action="branch-download-code" data-id="${esc(s.id)}">تنزيل الرمز</button><a class="btn secondary small" href="${esc(url)}" target="_blank" rel="noopener">فتح التسجيل</a></div></article>`;}).join('')}</div>`;
 if(view==='activity')return operationHTML();
 let html=branchOwner();
 if(view==='overview'){const box=document.createElement('div');box.innerHTML=html;box.querySelector('.analytics-toolbar')?.insertAdjacentHTML('afterbegin',`<label>الفرع <select data-branch-filter aria-label="فرع الإحصاءات">${branchOptions(branchFilter,true)}</select></label>`);box.querySelector('[data-branch-filter]')?.querySelector(`option[value="${CSS.escape(branchFilter)}"]`)?.setAttribute('selected','');const selected=analyticsScope==='all'?cards:cards.filter(s=>s.id===(analyticsScope==='current'?shop().id:analyticsScope));if(branchFilter!=='all')box.querySelector('.analytics-toolbar')?.insertAdjacentHTML('afterend','<p class="notice">الزيارات والعمليات حسب الفرع المحدد. عضويات العملاء وأرصدة المكافآت مشتركة بين فروع البطاقة.</p>');box.insertAdjacentHTML('beforeend',branchSummary(selected.flatMap(s=>s.logs)));html=box.innerHTML;}
 if(view==='employees'){const box=document.createElement('div');box.innerHTML=html;for(const row of box.querySelectorAll('tbody tr')){const b=row.querySelector('[data-action="toggle-employee"]');const e=shop().employees.find(e=>e.id===b?.dataset.id);if(e){if(row.cells[2])row.cells[2].textContent=branchLabel(e.branchId);row.querySelector('td:last-child')?.insertAdjacentHTML('beforeend',`<button class="btn secondary small" data-action="employee-branch" data-id="${esc(e.id)}">تحديد الفرع</button>`);}}html=box.innerHTML;}
 return html;
};
function operationRows(){const range=analyticsRange();return db.shops.filter(s=>!s.archivedAt&&(operationCard==='all'||s.id===operationCard)).flatMap(s=>s.logs.map(l=>({...l,cardTitle:s.card.title||s.name,cardId:s.id}))).filter(l=>(branchFilter==='all'||(l.branchId||'')===branchFilter)&&(operationKind==='all'||l.type===operationKind)&&(operationEmployee==='all'||l.employeeId===operationEmployee)&&l.time>=range.start&&l.time<=range.end&&(!operationSearch||[l.name,l.employee,l.branchName,l.cardTitle].join(' ').toLowerCase().includes(operationSearch.toLowerCase()))).sort((a,b)=>b.time-a.time);}
function operationHTML(){const rows=operationRows();return head('سجل موحد','سجل العمليات','افصل البيانات حسب البطاقة والفرع والموظف ونوع العملية والفترة.',`<button class="btn secondary" data-action="operations-export">تنزيل CSV</button>`)+`<div class="analytics-toolbar"><label>البطاقة <select data-operation="card" aria-label="بطاقة العمليات"><option value="all">جميع البطاقات</option>${db.shops.filter(s=>!s.archivedAt).map(s=>`<option value="${esc(s.id)}" ${operationCard===s.id?'selected':''}>${esc(s.card.title||s.name)}</option>`).join('')}</select></label><label>الفرع <select data-branch-filter aria-label="فرع العمليات">${branchOptions(branchFilter,true)}</select></label><label>الموظف <select data-operation="employee"><option value="all">الجميع</option>${shop().employees.map(e=>`<option value="${esc(e.id)}" ${operationEmployee===e.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select></label><label>النوع <select data-operation="kind">${[['all','الكل'],['stamp','زيارة / نقاط'],['redeem','صرف مكافأة'],['undo','تراجع']].map(([v,t])=>`<option value="${v}" ${operationKind===v?'selected':''}>${t}</option>`).join('')}</select></label><label>الفترة <select data-analytics="days" aria-label="فترة الإحصاءات">${[[1,'آخر ٢٤ ساعة'],[7,'٧ أيام'],[30,'٣٠ يومًا'],[180,'٦ أشهر'],[365,'سنة']].map(([v,t])=>`<option value="${v}" ${analyticsDays===v?'selected':''}>${t}</option>`).join('')}</select></label><input class="input" data-operation="search" aria-label="بحث العمليات" placeholder="بحث باسم العميل أو الموظف" value="${esc(operationSearch)}"><div class="analytics-calendar"><label>من <input type="date" data-analytics="from" aria-label="من تاريخ" value="${analyticsFrom}"></label><label>إلى <input type="date" data-analytics="to" aria-label="إلى تاريخ" value="${analyticsTo}"></label><button class="btn secondary small" data-action="analytics-range">عرض الفترة</button></div></div><section class="panel"><p class="sub">${fmt(rows.length)} عملية · ${esc(analyticsRange().label)}</p><div class="table-scroll"><table><thead><tr><th>التاريخ</th><th>البطاقة</th><th>الفرع</th><th>العميل</th><th>الموظف</th><th>العملية</th><th>المبلغ</th><th>الحالة</th></tr></thead><tbody>${rows.slice(0,500).map(l=>`<tr><td>${new Date(l.time).toLocaleString('ar-SA',{timeZone:'Asia/Riyadh'})}</td><td>${esc(l.cardTitle)}</td><td>${esc(l.branchName||branchLabel(l.branchId))}</td><td>${esc(l.name)}</td><td>${esc(l.employee)}</td><td>${({stamp:'زيارة / نقاط',redeem:'صرف مكافأة',undo:'تراجع'})[l.type]||esc(l.type)}</td><td>${Number.isFinite(l.saleAmount)?l.saleAmount.toLocaleString('ar-SA'):'—'}</td><td>${l.undone?'متراجع عنها':l.type==='undo'?'عملية تراجع':'مسجلة'}</td></tr>`).join('')||'<tr><td colspan="8">لا توجد عمليات مطابقة.</td></tr>'}</tbody></table></div>${rows.length>500?'<p class="sub">تعرض أول ٥٠٠ عملية. التنزيل يشمل كل النتائج.</p>':''}</section>`;}
const branchDesign=designHTML;
designHTML=function(){const box=document.createElement('div');box.innerHTML=branchDesign();box.querySelectorAll('.editor-step .editor-step-body')[1]?.insertAdjacentHTML('beforeend',branchChoices());return box.innerHTML;};
const branchEditor=bindEditor;
bindEditor=function(){branchEditor();document.querySelectorAll('[data-card-branch]').forEach(el=>el.addEventListener('change',()=>{draft.branchIds=Array.from(document.querySelectorAll('[data-card-branch]:checked'),e=>e.dataset.cardBranch);draft.branchRestricted=draft.branchIds.length>0;}));};
const branchModal=modal;
modal=function(...args){branchModal(...args);const f=document.querySelector('#employee-form');if(f&&!f.querySelector('[name=branchId]'))f.querySelector('button[type=submit],button.btn.primary')?.insertAdjacentHTML('beforebegin',`<label class="field"><span>الفرع · اختياري</span><select name="branchId">${branchOptions()}</select></label>`);};
const branchStaff=staffHTML;
staffHTML=function(){const box=document.createElement('div');box.innerHTML=branchStaff().replace('جرّب المسح الآن','إدخال رمز البطاقة').replace('اختر عميلًا لمحاكاة قراءة بطاقته.','استخدم القارئ أو اكتب رمز بطاقة العميل.').replace('افتح الكاميرا أو جرّب بطاقة من القائمة.','افتح الكاميرا لمسح بطاقة العميل.');const e=shop()?.employees.find(e=>e.id===staffEmployee);box.insertAdjacentHTML('afterbegin',`<div class="notice">الفرع: ${esc(branchLabel(e?.branchId))}</div><label class="field staff-sale" ${staffMode!=='stamp'?'hidden':''}><span>مبلغ العملية · ريال · اختياري</span><input class="input" id="staff-sale-amount" type="number" min="0" max="1000000" step="0.01" placeholder="اتركه فارغًا إذا لم ترغب بتسجيل المبيعات"><small>يسجل مع إضافة الزيارة أو النقاط فقط.</small></label>`);return box.innerHTML;};
document.addEventListener('change',e=>{if(e.target.matches('[data-branch-filter]')){branchFilter=e.target.value;render();}if(e.target.matches('[data-operation]')){const key=e.target.dataset.operation;if(key==='card')operationCard=e.target.value;if(key==='employee')operationEmployee=e.target.value;if(key==='kind')operationKind=e.target.value;if(key==='search')operationSearch=e.target.value;render();}});
function branchForm(b={}){modal(b.id?'تعديل الفرع':'إضافة فرع',`<form id="branch-form"><input type="hidden" name="id" value="${esc(b.id||'')}"><label class="field"><span>اسم الفرع</span><input class="input" name="name" required maxlength="60" value="${esc(b.name||'')}"></label><label class="field"><span>العنوان · اختياري</span><input class="input" name="address" maxlength="160" value="${esc(b.address||'')}"></label><p class="error" id="branch-error"></p><button class="btn primary full">حفظ الفرع</button></form>`);}
window.addEventListener('submit',async e=>{if(e.target.getAttribute("id")!=='branch-form')return;e.preventDefault();e.stopImmediatePropagation();if(!canOperate())return toast('يلزم تفعيل الاشتراك.');const d=new FormData(e.target);try{await serverCommand({action:d.get('id')?'update-branch':'create-branch',id:d.get('id'),name:d.get('name'),address:d.get('address'),cardIds:d.getAll('cards'),location:d.get('mapEnabled')?{lat:Number(d.get('lat')),lng:Number(d.get('lng'))}:null});document.querySelector('#modal').close();toast('تم حفظ الفرع.');}catch(err){document.querySelector('#branch-error').textContent=err.message;}},true);
window.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(!['card-peek','branch-create','branch-edit','branch-toggle','employee-branch','employee-branch-save','branch-copy-link','branch-download-code','operations-export'].includes(a))return;e.preventDefault();e.stopImmediatePropagation();try{if(a==='card-peek'){b.classList.toggle('opened');b.setAttribute('aria-expanded',String(b.classList.contains('opened')));return;}if(a==='branch-create'||a==='branch-edit'){if(!canOperate())throw Error('يلزم تفعيل الاشتراك.');branchForm(businessBranches().find(x=>x.id===b.dataset.id));}if(a==='branch-toggle'){await serverCommand({action:'toggle-branch',id:b.dataset.id});toast('تم تحديث الفرع.');}if(a==='employee-branch'){const employee=shop().employees.find(x=>x.id===b.dataset.id);modal('فرع الموظف',`<label class="field"><span>${esc(employee.name)}</span><select id="employee-branch-select">${branchOptions(employee.branchId)}</select></label><p class="sub">تؤثر التغييرات على العمليات التالية. يحفظ السجل الفروع السابقة.</p>`,`<button class="btn primary" data-action="employee-branch-save" data-id="${esc(employee.id)}">حفظ الفرع</button>`);}if(a==='employee-branch-save'){await serverCommand({action:'assign-employee-branch',id:b.dataset.id,branchId:document.querySelector('#employee-branch-select').value});document.querySelector('#modal').close();}if(a==='branch-copy-link')await navigator.clipboard.writeText(location.origin+'/?join='+encodeURIComponent(b.dataset.id));if(a==='branch-download-code'){const url=location.origin+'/?join='+encodeURIComponent(b.dataset.id);downloadBranchFile(qr(url),'image/svg+xml','registration-'+b.dataset.id+'.svg');}if(a==='operations-export'){const cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"',safe=v=>/^[\s]*[=+@-]/.test(String(v))?' '+v:v;const rows=operationRows().map(l=>[new Date(l.time).toISOString(),l.cardTitle,l.branchName||branchLabel(l.branchId),l.name,l.employee,l.type,l.saleAmount,l.undone?'undone':'recorded']);downloadBranchFile('\uFEFF'+[['التاريخ','البطاقة','الفرع','العميل','الموظف','النوع','المبلغ','الحالة'],...rows].map(r=>r.map(v=>cell(safe(v))).join(',')).join('\r\n'),'text/csv;charset=utf-8','rijaa-operations.csv');}}catch(err){toast(err.message);}},true);
function downloadBranchFile(value,type,name){const url=URL.createObjectURL(new Blob([value],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('keydown',e=>{const card=e.target.closest('.mobile-card-peek');if(card&&['Enter',' '].includes(e.key)){e.preventDefault();card.click();}});
const branchRender=render;render=function(){branchRender();document.querySelectorAll('.mobile-card-peek').forEach(el=>{const bottom=el.querySelector('.studio-bottom'),reward=el.querySelector('.studio-reward');if(bottom&&reward)el.style.setProperty('--peek-offset',Math.max(0,bottom.getBoundingClientRect().bottom-reward.getBoundingClientRect().bottom)+'px');});};
render();
